var t=`0651-benachin`;var n=`world-0651`;var a=`GM`;var o=`western-africa`;var r=4;var s=58;var h={en:`Benachin`,ua:`Беначин`};var g={en:`Benachin is a Gambia classic prepared with chicken thigh, yellow onion, tomato, tomato paste. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Беначин, страва кухні країни Гамбія зі складниками: куряче стегно, жовта цибуля, помідор, томатна паста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,690,`g`],[`sunflower-oil`,50,`ml`],[`yellow-onion`,190,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`tomato`,400,`g`],[`tomato-paste`,55,`g`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 26 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 26 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`parboiled-rice`,360,`g`],[`water`,690,`ml`],[`white-cabbage`,160,`g`],[`carrot`,180,`g`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 8 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 8 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:8,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,15,`g`]]}];var u={slug:t,id:n,country:`GM`,region:o,servings:4,minutes:58,title:h,text:g,steps:l};export{a as country,u as default,n as id,s as minutes,o as region,r as servings,t as slug,l as steps,g as text,h as title};